# ---------------------------------------------------------------- Blueprint prompt-library chapters
PROMPT_CHAPTERS = [
    ("10-prompts-project-foundation.md", "Prompts: Project Foundation", "P-01 to P-10", 5000),
    ("11-prompts-core-modules-phase-1.md", "Prompts: Core Modules (Phase 1)", "P-11 to P-22", 5500),
    ("12-prompts-finance-and-communication.md", "Prompts: Finance and Communication", "P-23 to P-32", 5000),
    ("13-prompts-phase-2-to-4-modules.md", "Prompts: Phase 2 to 4 Modules", "P-33 to P-48", 6500),
    ("14-prompts-quality-security-and-devops.md", "Prompts: Quality, Security and DevOps", "P-49 to P-60", 5000),
]
PROMPT_BRIEF = """This chapter of the Claude Code Prompt Library contains prompts {ids} — use the exact IDs and titles from the shared index. Start with a short intro (what these prompts build, the order to run them, which day of the 60-day plan uses them) and a table (ID | Prompt | Reads these docs | Builds | Typical time).

For EACH prompt write an H2 "P-xx — <title>" with:
1. **When to use** (one or two lines, with the sprint day or phase) and **Before you start** (pre-conditions: which earlier prompts must be done, env or accounts needed).
2. **The prompt** in a `text` code fence, ready to copy and paste into Claude Code. It must follow the anatomy from the *Working with Claude Code* chapter: CONTEXT (exact files to read first, for example docs/canon.md, docs/prd/<file>.md from the shared index, docs/schema/<file>.prisma, docs/api/<registry file>, docs/permissions.md), TASK (precise scope with PRD IDs such as FEE-API-01 to FEE-API-12 and screen IDs — open the registry files in `E:/mysaasschool/docs/src/_api/` and the schema README to use REAL endpoint IDs, paths, model names and permission keys), CONSTRAINTS (tenant scoping through the Prisma extension, requirePermission on every route, Zod validation from shared/, response envelope, error codes, transactions for money, no new tables or fields outside the schema, folder structure from the Blueprint, tests required), FILES to create or change (paths in the client/, server/, shared/ structure), ACCEPTANCE CHECKS (commands to run and behaviours to verify), and REPORT BACK (what Claude must summarise). Lines inside the fence at most 76 characters, plain ASCII (write Rs instead of the rupee sign). Each prompt should be 35–70 lines: specific, not generic.
3. **Follow-up prompts** — two or three short prompts in `text` fences for the usual next steps (fix failing tests, add the missing edge case, polish the UI).
4. **Review checklist** — 6–10 checks the founder does before committing (what to click, what to query, what must never happen — for example data of another organization appearing).
5. **Common mistakes Claude makes here and how to correct them** — a small table (Mistake | Fix prompt).

Write the chapter in several steps (a few prompts per step) so that nothing is cut off. Every prompt in the range must be present and complete."""


def write_brief(doc: str, file: str, title: str, words: int, body: str, research: bool = False) -> None:
    d = SRC / doc / "_briefs"
    d.mkdir(parents=True, exist_ok=True)
    (d / file).write_text(
        f"# Brief for {file}\n\nTitle: {title}\nMinimum words: {words}\nWeb research needed: {'yes' if research else 'no'}\n\n"
        f"## What this chapter must cover (every item, fully)\n\n{body}\n", encoding="utf-8")


prd_manifest = []
for file, title, words, body in CROSS:
    write_brief("prd", file, title, words, body)
    prd_manifest.append({"file": file, "title": title, "words": words, "kind": "cross"})
for file, name, code, registry, schema, focus in MODULES:
    body = MODULE_BRIEF.format(name=name, code=code, registry=registry, schema=schema, focus=focus)
    write_brief("prd", file, f"{name} Module", 4500, body)
    prd_manifest.append({"file": file, "title": f"{name} Module", "words": 4500, "kind": "module", "code": code})
prd_manifest.sort(key=lambda x: x["file"])
(BUILD / "manifest.prd.json").write_text(json.dumps(prd_manifest, indent=1), encoding="utf-8")

bp_path = BUILD / "manifest.blueprint.json"
bp = [m for m in json.loads(bp_path.read_text(encoding="utf-8")) if not m["file"].startswith(("10-", "11-", "12-", "13-", "14-"))]
for file, title, ids, words in PROMPT_CHAPTERS:
    write_brief("blueprint", file, title, words, PROMPT_BRIEF.format(ids=ids))
    bp.append({"file": file, "title": title, "words": words, "kind": "prompts"})
bp.sort(key=lambda x: x["file"])
bp_path.write_text(json.dumps(bp, indent=1), encoding="utf-8")
print("prd briefs:", len(prd_manifest), "| blueprint manifest:", len(bp))
